                            };
                            relId = $"{newtwin.Id}telemetryAccessControlPermissions->saFlexibilityProvidercLtJVPhoOIhL33bZPIMoo9ShquYa";
                            Program.dtClient.CreateOrReplaceRelationship(chess.Id + "telemetryAccessControlPermissions", relId, rel);
