                                        registered = true;

 
                                    }
                                }

                            // Now update the meter readings for this CHESS !
                            Console.WriteLine("Measurments # " + eVSEUpdate.ElectricMeter.Count);
                            foreach (Measurement measurement in eVSEUpdate.ElectricMeter)
